using MineralTrace, SHA, TOML
include(joinpath(@__DIR__,"attribute_calcite_bias.jl"))

function validate_scientific_models(root="results";project=dirname(@__DIR__),config=PHREEQCConfig(),pitzer=joinpath(dirname(config.database),"pitzer.dat"))
    env=environment_check(config);mkpath(root);dir=abspath(mktempdir(root;prefix="scientific-validation-",cleanup=false))
    registry=load_evidence_registry(joinpath(project,"data/models/evidence.toml"))
    profile=load_model_profiles(joinpath(project,"data/models/profiles.toml");registry)["calcite-co2-water-386"]
    # v0.7.1 controls are retained explicitly, including deliberately nonphysical limiting diagnostics.
    attribution,payload=attribute_calcite_bias(dir;project,config,pitzer,expanded_telemetry=true,return_payload=true)
    audits=Dict{String,Any}()
    for name in ("phreeqc.dat","pitzer.dat","ideal-co2.dat","davies-ions.dat")
        audits[name]=audit_database(joinpath(attribution,"databases",name);phases=profile.spec["required_phases"],species=profile.spec["required_species"])
    end
    # Different species sets are disclosed, never silently interpreted as a pure activity-model change.
    all(audits[n]["coverage_pass"] for n in ("phreeqc.dat","ideal-co2.dat","davies-ions.dat")) || error("Required baseline species missing")
    # Pitzer intentionally lacks explicit CaHCO3+ and neutral CaCO3: it represents a different aqueous convention.
    summaries=Dict{String,Any}[];details=Dict{String,Any}[]
    for name in payload["scenario_order"],basis in ("water","solution")
        rows=filter(r->r["scenario"]==name,payload["results"])
        m=comparison_statistics([r["observed_g_kg"] for r in rows],[r["prediction_$(basis)_g_kg"] for r in rows])
        m["scenario"]=name;m["mass_basis"]=basis;m["units"]="CaCO3-equivalent g/kg; relative errors are fractions"
        push!(summaries,m)
    end
    for r in payload["results"]
        row=r["selected"];num(k)=parse(Float64,row[k])
        name=r["scenario"];db=name=="pitzer_profile" ? "pitzer.dat" : name=="ideal_CO2_limit" ? "ideal-co2.dat" : name=="davies_charged_ions" ? "davies-ions.dat" : "phreeqc.dat"
        x=deepcopy(r);x["archive"]=joinpath(relpath(attribution,dir),r["archive"]);x["native_endpoint_archive"]=joinpath(relpath(attribution,dir),r["native_endpoint_archive"])
        x["signed_absolute_error_water_g_kg"]=r["prediction_water_g_kg"]-r["observed_g_kg"]
        x["signed_absolute_error_solution_g_kg"]=r["prediction_solution_g_kg"]-r["observed_g_kg"]
        x["observed_label"]="OBSERVED (digitized), unresolved g/kg denominator"
        x["pH_label"]="CALCULATED; measured endpoint pH UNKNOWN"
        x["boundary_label"]="ASSUMED fixed partial pressure; INFERRED from regulated bottle, not exact valve history"
        x["experimental_uncertainty"]="UNDETERMINED pointwise; no weighted acceptance"
        x["pressure_fugacity_audit"]=Dict("imposed_pco2_bar"=>r["pco2_bar"],"imposed_pco2_atm"=>bar_to_atm(r["pco2_bar"]),"actual_solution_pressure_atm"=>num("pressure_atm"),"log10_fugacity_atm"=>num("logf_CO2"),"fugacity_atm"=>10^num("logf_CO2"),"phi_inferred"=>r["phi_CO2"],"CO2_aqueous_activity"=>10^num("la_CO2"),"free_Ca_activity"=>10^num("la_Ca2"),"total_Ca_mol_kgw"=>num("total_Ca_mol_kgw"),"total_DIC_mol_kgw"=>num("total_DIC_mol_kgw"),"calcite_SI"=>num("si_Calcite"),"lk_Calcite"=>num("lk_Calcite"),"lk_CO2"=>num("lk_CO2"),"GFW_CaCO3_g_mol"=>num("gfw_Calcite"),"GFW_Ca_g_mol"=>num("gfw_Ca"))
        if name=="baseline"
            query=Dict{String,Any}("database_sha256"=>r["database_sha256"],"activity_model"=>"ion_association","gas_model"=>"peng_robinson","boundary"=>"fixed_partial_pressure","components"=>["Ca","C","H","O"],"minerals"=>["Calcite"],"temperature_c"=>24.,"pressure_bar"=>atm_to_bar(num("pressure_atm")),"pco2_bar"=>r["pco2_bar"],"ionic_strength_mol_kgw"=>num("ionic_strength"),"observable"=>"total_Ca_as_CaCO3_endpoint")
            x["applicability"]=evaluate_applicability(profile,query;registry,database_audit=audits[db])
        else
            x["applicability"]=Dict("profile_match_status"=>"exploratory_control_not_qualified","strict_qualified"=>false,"detail"=>r["meaning"])
        end
        push!(details,x)
    end
    for path in ("src","scripts","data","Project.toml","Manifest.toml");cp(joinpath(project,path),joinpath(dir,path));end
    cp(env.database,joinpath(dir,"database.dat"));cp(joinpath(attribution,"comparison.svg"),joinpath(dir,"comparison.svg"));cp(joinpath(attribution,"comparison.csv"),joinpath(dir,"comparison.csv"))
    columns=["point_id","scenario","pco2_bar","observed_g_kg","prediction_water_g_kg","prediction_solution_g_kg","signed_absolute_error_water_g_kg","signed_absolute_error_solution_g_kg","delta_water","delta_solution","prediction_change_water_percent","prediction_change_solution_percent","phi_CO2"]
    open(joinpath(dir,"comparison.csv"),"w") do io
        println(io,join(columns,','));for r in details;println(io,join([r[k] for k in columns],','));end
    end
    open(io->TOML.print(io,Dict("profile"=>profile.spec);sorted=true),joinpath(dir,"model-profile.toml"),"w")
    provenance=Dict("package_version"=>string(pkgversion(MineralTrace)),"julia_version"=>string(VERSION),"database_sha256"=>env.database_sha256,"executable_sha256"=>bytes2hex(sha256(read(env.executable))),"profile_sha256"=>bytes2hex(sha256(codeunits(MineralTrace.json_value(profile.spec)))),"evidence_registry_sha256"=>registry.fingerprint,"observation_sha256"=>OBS_HASH,"metadata_audit_sha256"=>bytes2hex(sha256(read(joinpath(project,"data/validation/REFLECT_METADATA_AUDIT_V080.json")))),"source_sha256"=>Dict(relpath(joinpath(d,f),project)=>bytes2hex(sha256(read(joinpath(d,f)))) for (d,_,fs) in walkdir(joinpath(project,"src")) for f in fs),"script_sha256"=>bytes2hex(sha256(read(@__FILE__))),"attribution_script_sha256"=>bytes2hex(sha256(read(joinpath(@__DIR__,"attribute_calcite_bias.jl")))))
    result=Dict("provenance"=>provenance,"database_audits"=>audits,"statistics"=>summaries,"calculated_comparisons"=>details,"scientific_conclusion"=>"experimentally_challenged; discrepancy unresolved; no parameter fitting; no alternative certified")
    write(joinpath(dir,"results.json"),MineralTrace.json_value(result)*"\n")
    deterministic=deepcopy(result)
    for r in deterministic["calculated_comparisons"];delete!(r,"archive");delete!(r,"native_endpoint_archive");end
    write(joinpath(dir,"analysis.json"),MineralTrace.json_value(deterministic)*"\n")
    write(joinpath(dir,"reproduce.jl"),"include(joinpath(@__DIR__,\"scripts/validate_scientific_models.jl\"))\nvalidate_scientific_models(joinpath(@__DIR__,\"reproduced\");project=@__DIR__,config=PHREEQCConfig(database=joinpath(@__DIR__,\"database.dat\")),pitzer=joinpath(@__DIR__,\"data/validation/v071/databases/pitzer.dat\"))\n")
    metricrows=join(["<tr><td>$(m["scenario"])</td><td>$(m["mass_basis"])</td><td>$(m["mean_signed_error"])</td><td>$(m["mean_absolute_error"])</td><td>$(m["root_mean_square_error"])</td><td>$(100*m["maximum_absolute_relative_error"])</td></tr>" for m in summaries])
    rows=join(["<tr><td>$(r["point_id"])</td><td>$(r["scenario"])</td><td>$(r["observed_g_kg"])</td><td>$(r["prediction_water_g_kg"])</td><td>$(r["prediction_solution_g_kg"])</td><td>$(r["prediction_water_g_kg"]-r["observed_g_kg"])</td><td>$(100*r["delta_water"])</td><td>$(100*r["delta_solution"])</td><td>$(r["prediction_change_water_percent"])</td><td>$(r["phi_CO2"])</td><td><a href='$(r["archive"])/input.pqi'>deck</a></td></tr>" for r in details])
    page="""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>MineralTrace v0.8.0 Scientific Model Validation &amp; Applicability</title><style>body{max-width:1200px;margin:32px auto;padding:0 20px;font:15px/1.6 system-ui;color:#23384a}svg{width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{border:1px solid #ccd3da;padding:7px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f4f7;padding:15px}.warning{border-left:5px solid #c17b1a;padding:12px;background:#fff5df}</style><h1>Scientific Model Validation &amp; Applicability</h1><p class="warning"><b>Experimentally challenged; discrepancy unresolved.</b> Engine consistency, chemical conservation, empirical accuracy and conditional formation-mechanism screening are distinct. No model is tuned or selected as validated. No crystallization time is predicted.</p><h2>1. Identity, experimental source and observables</h2><p>REFLECT D2.3, DOI 10.48440/gfz.4.8.2023.001, pp.22–23 and Fig.22 p.26. OBSERVED: five frozen digitized 24 °C pure-water calcite-equivalent g/kg points from EDTA calcium analysis. ASSUMED: initially pure water, finite calcite boundary inventory and nonexhausted numerical CO2 reservoir. INFERRED: regulated-bottle apparatus supports fixed partial-pressure approximation. UNDETERMINED: kg denominator, exact pointwise loading/dilution/uncertainty, gas purity and valve history. Calculated pH is not measured pH; analytical EDTA pH 10 is not the fluid endpoint pH.</p><p><a href="data/sources/REFLECT-D23-2023.pdf">Original source</a> · <a href="data/validation/REFLECT_METADATA_AUDIT_V080.md">Field audit</a> · <a href="model-profile.toml">Model profile</a></p><pre>$(MineralTrace.html(provenance))</pre><h2>2. Computed comparisons, signed errors and one-choice controls</h2>$(read(joinpath(dir,"comparison.svg"),String))<p>CALCULATED points only; no invented experimental curves or uncertainty bands. Baseline five-point predictions remain unchanged. Ideal gas and 1-atm liquid-pressure decoupling are limiting diagnostics, not physically accepted reconstructions. Pitzer is a whole-profile exploratory comparison with different species/conventions, not an isolated activity effect or validated substitute. Missing pointwise uncertainty precludes weighted statistical acceptance.</p><table><tr><th>Point</th><th>Choice</th><th>Observed g/kg</th><th>Calculated kg water</th><th>Calculated kg solution</th><th>Signed absolute error water</th><th>Signed relative % water</th><th>Signed relative % solution</th><th>Change % from baseline water</th><th>phi CO2</th><th>Raw deck</th></tr>$rows</table><h2>3. Descriptive error statistics</h2><p>Absolute metrics in CaCO3-equivalent g/kg. No acceptance score, sigma, p-value, model ranking or optimized combination is computed.</p><table><tr><th>Choice</th><th>kg basis</th><th>Mean signed</th><th>MAE</th><th>RMSE</th><th>Max abs relative %</th></tr>$metricrows</table><h2>4. Gas, pressure and database audit</h2><p>1 atm = 1.01325 bar; EQUILIBRIUM_PHASES receives log10(pCO2/atm), not log fugacity. Native PR availability is structurally audited and its actual effect checked with inferred phi = f/p. Aqueous PRESSURE, activities, log K, SI, total Ca/DIC and formula weights are independently emitted. PHASES gas inventory is a numerical boundary stock, not a measured headspace. Fixed partial pressure, fixed total pressure GAS_PHASE and finite fixed volume are not interchangeable; missing headspace/valve data prevent a quantitative finite-gas reconstruction.</p><pre>$(MineralTrace.html(audits))</pre><h2>5. Applicability and unknowns</h2><p>Profiles match exact database/activity/gas/boundary, components, phases, T/P/I and observable. Execution/review bounds are not experimentally validated domains. Five jointly sampled conditions are not a validated continuous pressure interval. No current profile qualifies strict path applicability. Independent endpoint evidence does not validate pH, reaction rates, path chronology, saline systems or Calcite–Fluorite no-gas discovery.</p><p>The bias is sensitive to the bundled aqueous thermodynamic profile. Vapor-pressure approximation and modest liquid-pressure variations are too small in these controls; omitting PR makes the high bias larger. This does not validate PR or identify a unique error source. Mass basis, analytical worksheets, boundary history and database calibration lineage remain unresolved. Seek pointwise raw analyses plus independently held-out low-temperature high-pCO2 Ca/DIC endpoints, rather than fitting log K.</p><h2>6. Reproduction and evidence</h2><p><a href="analysis.json">Deterministic calculations, statistics, audits and profile matches</a> · <a href="results.json">Raw archive links</a> · <a href="comparison.csv">Per-point values</a> · <a href="data/models/evidence.toml">Separate evidence registry</a></p><pre>PHREEQC_EXECUTABLE=/absolute/path/to/phreeqc julia --project=. reproduce.jl</pre><p>Keep the complete export, including inputs, raw outputs, state dumps, exact database/source/profile/protocol snapshots and software hashes. Official Examples 6/7/22 are engine references only; their results never grant experimental support.</p></html>"""
    write(joinpath(dir,"report.html"),page);println("Scientific report: ",joinpath(dir,"report.html"));dir
end
if abspath(PROGRAM_FILE)==@__FILE__
    validate_scientific_models(isempty(ARGS) ? "results" : ARGS[1])
end
